import {mountTeachers} from './teachers.js?v=1';
import {mountEditorTools,previewURL} from './editor-tools.js?v=1';
let editorTools=null;
let disposeTeachers=null;
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v));
const state={lang:localStorage.getItem('qrayti-admin-language')||'ar',tab:'overview',session:null,content:null,revision:0,publishedRevision:0,dirty:false,media:[],versions:[],files:[],static:[],overrides:[],page:1,query:'',filter:'all',picked:null,selecting:false,device:'desktop',route:'/#/welcome',queue:[],uploading:false,faq:null,mascot:null};
state.fields={};state.pendingBound={};state.previewSequence=0;state.teacherWorkspace={};
const previewTextPaths=new Set(['home.badge','home.title','home.accent','home.description','home.cta','home.install','brand.name']);
const t=(ar,en)=>state.lang==='ar'?ar:en;
const paths={home:'M3 11 12 3l9 8M5 10v11h5v-6h4v6h5V10',edit:'m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15v5',template:'M3 3h18v18H3zM3 9h18M9 9v12',image:'M3 3h18v18H3zM3 16l6-6 5 5 3-3 4 4M16 7h.01',book:'M3 4h7l2 2 2-2h7v16h-7l-2 1-2-1H3zM12 6v15',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',chat:'M3 4h18v13H8l-5 4V4',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',settings:'M12 3v3m0 12v3M3 12h3m12 0h3M6 6l2 2m8 8 2 2M6 18l2-2m8-8 2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',arrow:'M5 12h14m-5-5 5 5-5 5',menu:'M4 6h16M4 12h16M4 18h16',check:'m5 12 4 4L20 5'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.edit}"/></svg>`;
const flag=lang=>lang==='en'?'<svg class="flag" viewBox="0 0 60 40" aria-hidden="true"><path fill="#173669" d="M0 0h60v40H0z"/><path stroke="#fff" stroke-width="8" d="m0 0 60 40M60 0 0 40"/><path stroke="#cd3547" stroke-width="3" d="m0 0 60 40M60 0 0 40"/><path stroke="#fff" stroke-width="13" d="M30 0v40M0 20h60"/><path stroke="#cd3547" stroke-width="8" d="M30 0v40M0 20h60"/></svg>':'<svg class="flag" viewBox="0 0 60 40" aria-hidden="true"><path fill="#16814d" d="M0 0h60v40H0z"/><text x="30" y="25" text-anchor="middle" fill="white" font-size="14" font-family="Tahoma">العربية</text></svg>';
const tabs=()=>[['overview',t('نظرة عامة','Overview'),'home'],['editor',t('محرّر الموقع','Website editor'),'edit'],['templates',t('قوالب الواجهة','Templates'),'template'],['media',t('مكتبة الصور','Media library'),'image'],['courses',t('الكور والملفات','Courses & files'),'book'],['upload',t('إضافة كور','Upload courses'),'upload'],['teachers',t('الأساتذة','Teachers'),'book'],['faq',t('بديس القراي','FAQ / Badis'),'chat'],['mascot',t('حما غراب','Hama Ghrab'),'chat'],['history',t('سجل النشر','Publish history'),'clock']];
const fmt=n=>n>1048576?(n/1048576).toFixed(1)+' MB':Math.round(n/1024)+' KB';
function notice(message,bad=false){const el=$('#notice');el.textContent=message;el.className='notice'+(bad?' bad':'');el.hidden=false;clearTimeout(notice.timer);notice.timer=setTimeout(()=>el.hidden=true,bad?8000:4000);}
async function api(url,options={}){const r=await fetch(url,{credentials:'same-origin',cache:'no-store',...options,headers:{Accept:'application/json',...options.headers}});if(r.status===204)return {};const data=await r.json().catch(()=>({error:'HTTP '+r.status}));if(!r.ok){const e=new Error(data.error||'HTTP '+r.status);e.status=r.status;throw e;}return data;}
const send=(url,method,body)=>api(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
async function run(fn,button){if(button)button.disabled=true;try{await fn();}catch(e){notice(e.message,true);}finally{if(button?.isConnected)button.disabled=false;}}
function setPath(obj,path,value){const parts=path.split('.');let node=obj;for(const p of parts.slice(0,-1))node=node[p];node[parts.at(-1)]=value;}
function valueAt(obj,path){return path.split('.').reduce((a,b)=>a?.[b],obj)??'';}
function field(label,name,value='',type='text',wide=false){return `<label class="${wide?'wide':''}"><span>${label}</span>${type==='textarea'?`<textarea name="${name}" rows="3">${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}">`}</label>`;}
function bound(label,path,type='text',hint=''){const v=state.fields[path]?.value??valueAt(state.content,path);return `<label><span>${label}</span>${type==='textarea'?`<textarea rows="3" data-bind="${path}">${esc(v)}</textarea>`:`<input data-bind="${path}" type="${type}" value="${esc(v)}" placeholder="${esc(t('اختياري','Optional'))}">`}${hint?`<small>${hint}</small>`:''}</label>`;}
function head(title,desc,action=''){return `<div class="page-head"><div><span class="eyebrow">QRAYTI / ADMIN V2</span><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function card(title,body){return `<section class="card"><h2>${title}</h2>${body}</section>`;}
function empty(message){return `<div class="empty">${message}</div>`;}
function status(status){return `<span class="status ${esc(status)}">${{published:t('منشور','Published'),draft:t('مسودة','Draft'),hidden:t('مخفي','Hidden')}[status]||esc(status)}</span>`;}
function savebar(){return `<div class="save-bar"><div><span id="saveState" class="status ${state.dirty?'draft':'good'}">${state.dirty?t('تغييرات لم تحفظ','Unsaved changes'):t('المسودة محفوظة','Draft saved')}</span><small>${t('الحفظ لا يغيّر الموقع. انشر عندما تكون جاهزًا.','Saving does not publish. Publish when you are ready.')}</small></div><div class="actions"><button data-action="save">${t('حفظ المسودة','Save draft')}</button><button class="primary" data-action="publish">${t('معاينة ونشر','Review & publish')}</button></div></div>`;}
function themeButton(){
  const dark=document.documentElement.dataset.theme==='dark',label=dark?t('الوضع الفاتح','Light mode'):t('الوضع الداكن','Dark mode');
  return `<button data-theme-toggle aria-label="${label}" title="${label}"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${dark?'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>':'<path d="M20 15.5A9 9 0 0 1 8.5 4a9 9 0 1 0 11.5 11.5Z"/>'}</svg><span class="theme-label">${label}</span></button>`;
}
function toggleTheme(){
  const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';
  document.documentElement.dataset.theme=theme;
  try{localStorage.setItem('qrayti-admin-theme',theme);}catch{}
  // Keep the button and orb mounted so animation, keyboard focus and unsaved fields survive.
  const button=$('[data-theme-toggle]');button.setAttribute('aria-checked',String(theme==='dark'));
  button.title=theme==='dark'?t('الوضع الفاتح','Light mode'):t('الوضع الداكن','Dark mode');
}
function languages(){document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';$('#languageBar').innerHTML=['ar','en'].map(l=>`<button data-lang="${l}" class="${state.lang===l?'active':''}" aria-pressed="${state.lang===l}">${flag(l)} ${l==='ar'?'العربية':'English'}</button>`).join('')+themeButton();}
function login(){disposeTeachers?.();disposeTeachers=null;state.teacherWorkspace={};languages();$('#workspace').hidden=true;$('#login').hidden=false;$('#loginForm').innerHTML=`<div class="mark">ق</div><p class="eyebrow">QRAYTI / ADMIN V2</p><h1>${t('قرايتي، تحت تحكّمك.','Your Qrayti workspace.')}</h1><p>${t('عدّل الموقع، نظّم الكور وانشر التغييرات من مكان واحد.','Edit your website, organize courses and publish changes from one place.')}</p>${field(t('كلمة السر','Password'),'password','','password')}<button class="primary" type="submit">${t('دخول إلى الإدارة','Sign in')}</button><div id="loginError" class="error" role="alert"></div><p><a href="/">${t('الرجوع إلى قرايتي','Back to Qrayti')} ↗</a></p>`;$('#loginForm input').autocomplete='current-password';}
function shell(){languages();$('#login').hidden=true;$('#workspace').hidden=false;const list=tabs();$('#sidebar').innerHTML=`<div class="brand"><span class="mark">ق</span><div><b>Qrayti</b><small>ADMIN WORKSPACE · V2</small></div></div><div class="nav-label">${t('مساحة الإدارة','YOUR WORKSPACE')}</div>${list.map(([id,label,i])=>`<button class="nav-btn ${state.tab===id?'active':''}" data-nav="${id}">${icon(i)}${label}</button>`).join('')}<div class="sidebar-bottom">${esc(state.session.email)}<br><a href="/" target="_blank" rel="noopener">${t('افتح الموقع','Open website')} ↗</a><button class="nav-btn" data-action="logout">${t('تسجيل الخروج','Sign out')}</button></div>`;$('#topbar').innerHTML=`<button class="menu" data-action="menu" aria-label="${t('القائمة','Menu')}">${icon('menu')}</button><div><span>Qrayti</span><span>/</span><strong>${list.find(x=>x[0]===state.tab)?.[1]}</strong></div>`;}
function allFiles(){const overrides=new Map(state.overrides.map(x=>[x.id,x]));return [...state.static.map(x=>({...x,status:'published',...overrides.get(x.id),origin:'static'})),...state.files.map(x=>({...x,origin:'admin'}))];}
function overview(){const files=allFiles();return head(t('أهلا، أمين.','Welcome back, Amine.'),t('كل ما يلزمك لإدارة قرايتي، واضح وفي بلاصة واحدة.','Everything you need to run Qrayti, in one place.'))+`<div class="stats">${[[files.length,t('ملف في المكتبة','Library files'),'book'],[new Set(files.map(x=>x.subjectId)).size,t('مادة دراسية','Subjects'),'template'],[state.media.length,t('صورة في المكتبة','Uploaded images'),'image'],[state.publishedRevision,t('نسخة الموقع المنشورة','Published site revision'),'clock']].map(([n,l,i])=>`<article class="stat">${icon(i)}<strong>${n.toLocaleString()}</strong><span>${l}</span></article>`).join('')}</div><section class="welcome-card"><div><span class="eyebrow">WEBSITE STUDIO</span><h2>${t('كلمة، صورة، أو واجهة جديدة.','A word, a photo, a new homepage.')}</h2><p>${t('افتح المحرّر، اضغط على النص أو الصورة في المعاينة، وعدّلها. جرّب على الهاتف والكمبيوتر قبل النشر.','Open the editor, select text or an image in the preview, and change it. Check phone and desktop views before publishing.')}</p><button class="primary" data-nav="editor">${t('افتح محرّر الموقع','Open website editor')} ↗</button></div><div class="welcome-art" aria-hidden="true"><div><i></i><i></i><i></i><i></i></div><span>✎</span></div></section><div class="quick-grid">${[['upload',t('أضف كور جديد','Add new courses'),t('اختار المادة وارفع الملفات.','Choose a subject and upload files.'),'upload'],['templates',t('بدّل قالب الرئيسية','Choose a homepage template'),t('معاينة القالب قبل تفعيله.','Preview a template before activating it.'),'template'],['history',t('ارجع لنسخة سابقة','Restore a previous version'),t('كل نشر محفوظ في السجل.','Every published revision is saved.'),'clock']].map(([n,l,d,i])=>`<button class="quick-card" data-nav="${n}">${icon(i)}<span><b>${l}</b><small>${d}</small></span></button>`).join('')}</div>`;}
function imageField(label,path,altPath=''){return `<label><span>${label}</span><div class="actions"><button data-media-target="${path}">${t('اختار صورة','Choose image')}</button><button data-clear-image="${path}">${t('استعمل الأصل','Use original')}</button></div><small dir="ltr">${esc(valueAt(state.content,path))}</small></label>${altPath?bound(t('وصف الصورة','Image description'),altPath):''}`;}
function editor(){return head(t('محرّر الموقع','Website editor'),t('تصفح الصفحات في المعاينة، ثم فعّل «اختار عنصر» لتعديل كلمة أو صورة.','Browse pages in the preview, then enable “Select element” to edit text or an image.'))+savebar()+`<div class="editor-layout"><div class="editor-controls"><details class="card" open><summary>${t('الصفحة الرئيسية','Homepage')}</summary>${bound(t('السطر الصغير','Small heading'),'home.badge')}${bound(t('العنوان الرئيسي','Main heading'),'home.title')}${bound(t('العنوان الملوّن','Accent heading'),'home.accent')}${bound(t('وصف الموقع','Description'),'home.description','textarea')}${bound(t('زر اكتشاف الكور','Course button label'),'home.cta')}${bound(t('زر التطبيق','App button label'),'home.install')}${imageField(t('صورة في الرئيسية (اختياري)','Homepage image (optional)'),'home.image','home.imageAlt')}<label class="check"><input type="checkbox" data-bind="home.showCampuses" ${state.content.home.showCampuses?'checked':''}>${t('إظهار شريط الجامعات','Show university strip')}</label><label class="check"><input type="checkbox" data-bind="home.motion" ${state.content.home.motion?'checked':''}>${t('حركات الواجهة','Homepage motion')}</label></details><details class="card"><summary>${t('الهوية والتواصل','Brand & contact')}</summary>${bound(t('اسم الموقع','Site name'),'brand.name')}${imageField(t('شعار الموقع','Site logo'),'brand.logo')}${bound(t('إيميل التواصل','Contact email'),'contact.email','email')}${bound(t('صفحة Instagram','Instagram profile'),'contact.instagram','url')}${bound(t('اللون الأساسي','Primary color'),'colors.primary')}${bound(t('اللون الثاني','Secondary color'),'colors.secondary')}<p class="hint">${t('الألوان بصيغة #2563eb. اتركها فارغة للألوان الحالية.','Use a color such as #2563eb. Leave blank for existing colors.')}</p></details><section id="pickedPanel" class="card picked">${pickedHTML()}</section><section class="card edit-list-card"><h2>${t('تعديلات النصوص والصور','Text & image overrides')}</h2><div id="editList">${editsHTML()}</div></section></div><section class="preview-panel"><div class="preview-tools"><div class="actions"><button data-action="select" class="${state.selecting?'active':''}" aria-pressed="${state.selecting}">${t('اختار عنصر','Select element')}</button><button data-preview-home>${t('الرئيسية','Home')}</button></div><div class="actions"><button data-device="desktop" class="${state.device==='desktop'?'active':''}">${t('كمبيوتر','Desktop')}</button><button data-device="phone" class="${state.device==='phone'?'active':''}">${t('هاتف','Phone')}</button></div></div><div class="preview-address" id="previewAddress">${esc(state.route)}</div><div class="preview-body ${state.device==='phone'?'phone':''}"><iframe id="sitePreview" title="${t('معاينة قرايتي','Qrayti preview')}" src="${esc(previewURL(state.route))}"></iframe></div><div class="preview-hint">${t('عطّل «اختار عنصر» لتصفح الكور وفتح النوافذ. التعديلات هنا مسودة حتى تنشرها.','Turn off “Select element” to browse courses and open dialogs. Changes here remain a draft until published.')}</div></section></div>`;}
function selectPicked(d){state.picked=d;$('#pickedPanel').innerHTML=pickedHTML();$('#pickedPanel').scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});$('#pickedValue')?.focus({preventScroll:true});}
function pickedHTML(){const p=state.picked;if(!p)return `<h2>${t('اضغط على شيء في المعاينة','Select something in the preview')}</h2><p>${t('نصوص، عناوين، أزرار أو صور. تنجم تتنقل لأي مادة أو صفحة وتعدّل النص الموجود فيها.','Text, headings, buttons or images. Navigate to any subject or page and edit its visible copy.')}</p>`;return `<h2>${p.kind!=='image'?t('تعديل النص','Edit text'):t('تبديل الصورة','Replace image')}</h2><small class="hint" dir="ltr">${esc(p.route)}</small><p>${esc(p.original).slice(0,280)}</p>${p.kind!=='image'?`<label>${t('النص الجديد','New text')}<textarea id="pickedValue" rows="4">${esc(p.value)}</textarea></label>`:`<button data-media-target="picked">${t('اختار من الصور','Choose from library')}</button><input id="pickedValue" value="${esc(p.value)}" readonly><label>${t('وصف الصورة','Image description')}<input id="pickedAlt" value="${esc(p.alt||'')}"></label>`}<label class="check"><input id="pickedGlobal" type="checkbox">${t('نفس التغيير في كل الصفحات','Apply wherever this appears')}</label><button class="primary" data-action="applyPicked">${t('طبّق في المعاينة','Apply to preview')}</button>`;}
function editsHTML(){const all=[...state.content.texts.map(x=>({...x,kind:'texts'})),...state.content.images.map(x=>({...x,kind:'images'}))];return all.length?`<div class="edit-list">${all.map(x=>`<div class="edit-row"><div><p>${esc(x.value??x.alt??x.src).slice(0,100)}</p><small>${esc(x.route)}</small></div><button data-remove-edit="${esc(x.id)}" data-kind="${x.kind}" aria-label="${t('إلغاء هذا التعديل','Remove this override')}">×</button></div>`).join('')}</div>`:empty(t('ما زدت حتى تعديل بصري.','No visual overrides yet.'));}
function templates(){const current=state.content.template;return head(t('قوالب الرئيسية','Homepage templates'),t('اختار القالب، شوفه في المعاينة، وبعد انشر. المحتوى يبقى محفوظًا.','Choose a template, preview it, then publish. Your content stays saved.'))+savebar()+`<div class="template-grid">${[['classic',t('قرايتي الأصلي','Qrayti Classic'),t('الواجهة الحالية بنفس ترتيبها وألوانها.','Your current homepage layout and colors.'),''],['classic-motion',t('قرايتي مع الحركة','Qrayti Motion'),t('نفس الواجهة مع ظهور تدريجي وتفاعل الأزرار.','The same layout with entrance and interaction motion.'),'motion'],['future',t('قوالب جديدة','More layouts'),t('القوالب الجديدة مازالت قيد التطوير. تظهر هنا وقت تكون جاهزة.','New layouts are still being developed. They will appear here when ready.'),'future']].map(([id,name,desc,cl])=>`<section class="card template-card"><div class="template-sample ${cl}">${id==='future'?icon('template'):'<div class="sample-lines"><i></i><i></i><i></i><i></i></div>'}</div><div><span class="status ${id===current?'good':''}">${id===current?t('مختار في المسودة','Selected in draft'):id==='future'?t('قيد التطوير','In development'):t('جاهز','Ready')}</span><h2>${name}</h2><p>${desc}</p><button data-template="${id}" ${id==='future'?'disabled':''} class="${id===current?'primary':''}">${id===current?t('معاينة','Preview'):t('اختار القالب','Select template')}</button></div></section>`).join('')}</div>`;}
function mediaCards(pick=false){return state.media.length?`<div class="media-grid">${state.media.map(x=>`<article class="media-card"><img src="${esc(x.url)}" alt="${esc(x.name)}" loading="lazy"><div><b>${esc(x.name)}</b><small>${fmt(x.size)}</small><button ${pick?'data-use-media':'data-copy-media'}="${esc(x.url)}">${pick?t('استعمل الصورة','Use image'):t('نسخ الرابط','Copy URL')}</button></div></article>`).join('')}</div>`:empty(t('ارفع أول صورة. PNG، JPG أو WebP، حتى 8 MB.','Upload your first image. PNG, JPG or WebP, up to 8 MB.'));}
function media(){return head(t('مكتبة الصور','Media library'),t('صورك محفوظة هنا. استعملها في الشعار، الرئيسية، أو بدّل أي صورة من المحرّر.','Your uploaded images, ready for the logo, homepage or visual editor.'),`<label class="primary" style="padding:12px 17px;border-radius:9px;cursor:pointer">${t('رفع صور','Upload images')}<input data-upload-media type="file" accept="image/png,image/jpeg,image/webp" multiple hidden></label>`)+`<div class="help-note" style="margin-bottom:22px">${t('الرفع يحفظ الصورة فقط. لن تظهر في الموقع حتى تختارها وتنشر التعديل.','Uploading only stores an image. It appears on the site after you choose it and publish the change.')}</div>`+mediaCards();}
function courseRows(){let files=allFiles();if(state.filter!=='all')files=files.filter(x=>state.filter==='static'?x.origin==='static':state.filter==='admin'?x.origin==='admin':x.status===state.filter);const q=state.query.toLowerCase();if(q)files=files.filter(x=>[x.displayName,x.subjectName,x.group,x.sourceUniversity,x.sourceInstructor].some(v=>String(v||'').toLowerCase().includes(q)));const pages=Math.max(1,Math.ceil(files.length/40));state.page=Math.min(state.page,pages);const rows=files.slice((state.page-1)*40,state.page*40);return `<div class="table-wrap"><table><thead><tr>${[t('الملف','File'),t('المادة والمكان','Subject & context'),t('المصدر','Source'),t('الحالة','Status'),t('إجراءات','Actions')].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.displayName)}</b><small>${esc(x.group)} · ${fmt(x.size)}</small></td><td>${esc(x.subjectName)}<small>${esc(x.licence.toUpperCase())} · Y${x.year} / S${x.semester}</small></td><td>${esc(x.sourceUniversity||'—')}<small>${esc(x.sourceInstructor||x.sourceInstitution||'')}</small></td><td>${status(x.status)}<small>${x.origin==='static'?t('المكتبة الأصلية','Original library'):t('رفع من الإدارة','Admin upload')}</small></td><td><button data-edit-file="${esc(x.id)}">${t('تعديل','Edit')}</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?empty(t('لا نتائج.','No matching files.')):''}<div class="pager"><button data-page="${state.page-1}" ${state.page<=1?'disabled':''}>${t('السابق','Previous')}</button><span>${state.page} / ${pages} · ${files.length} ${t('ملف','files')}</span><button data-page="${state.page+1}" ${state.page>=pages?'disabled':''}>${t('التالي','Next')}</button></div>`;}
function courses(){return head(t('الكور والملفات','Courses & files'),t('غيّر الأسماء، الشابترات والمصادر، أو أخفي الملفات. تعديلات الكور تُحفظ مباشرة.','Edit names, chapters and sources, or hide files. Course changes save immediately.'),`<button class="primary" data-nav="upload">+ ${t('إضافة كور','Add courses')}</button>`)+`<div class="toolbar"><input id="courseSearch" value="${esc(state.query)}" placeholder="${t('ابحث باسم الملف، المادة، الجامعة أو الأستاذ…','Search file, subject, university or teacher…')}"><select id="courseFilter">${[['all',t('كل الملفات','All files')],['admin',t('رفع الإدارة','Admin uploads')],['static',t('المكتبة الأصلية','Original library')],['published',t('منشور','Published')],['draft',t('مسودة','Draft')],['hidden',t('مخفي','Hidden')]].map(([v,l])=>`<option value="${v}" ${state.filter===v?'selected':''}>${l}</option>`).join('')}</select><button data-action="export">${t('نسخة احتياطية','Export backup')}</button></div><div id="courseRows">${courseRows()}</div>`;}
function options(list,value){return list.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('');}
const categories=[['cours','Cours'],['td','TD'],['tp','TP'],['exam','Examens'],['resume','Résumés'],['qcm','QCM'],['extra','Fichiers']];
function upload(){return head(t('أضف كور لقرايتي','Add courses to Qrayti'),t('اختار الوجهة، أضف الملفات، راجع الأسماء ثم ارفع. تظهر الملفات المنشورة في الكاتالوغ المشترك.','Choose a destination, add files, review names and upload. Published files appear in the shared catalog.'))+`<section class="card"><div class="card-head"><h2>01 / ${t('وجهة الملفات','Destination')}</h2><span class="status">${t('الموقع والتطبيق','Website & app')}</span></div><form id="uploadContext" class="form-grid"><label>${t('الإجازة','Licence')}<select name="licence">${options([['info','Sciences de l’Informatique'],['lt','LT'],['lce','LCE']],'info')}</select></label><label>${t('السنة','Year')}<select name="year">${options([[1,'1'],[2,'2']],1)}</select></label><label>${t('السداسي','Semester')}<select name="semester">${options([[1,'S1'],[2,'S2']],1)}</select></label><label>${t('الشعبة','Track')}<select name="track">${options([['common',t('جذع مشترك','Common')],['genie','Génie Logiciel'],['multimedia','Multimédia']],'common')}</select></label><label class="wide">${t('المادة','Subject')}<select name="subjectId" id="uploadSubject"></select></label><div id="newSubject" class="form-grid wide" hidden>${field(t('اسم المادة','Subject name'),'subjectName')}${field(t('معرّف المادة (حروف لاتينية)','Subject ID (Latin letters)'),'newSubjectId')}${field(t('اسم بالعربية','Arabic name'),'subjectAr')}${field(t('اختصار','Abbreviation'),'subjectAbbr')}</div><label>${t('القسم','Category')}<select name="category">${options(categories,'cours')}</select></label>${field(t('الشابتر / المجموعة','Chapter / group'),'group','Cours')}${field(t('الجامعة','University'),'sourceUniversity')}${field(t('الكلية / المعهد','Faculty / institute'),'sourceInstitution')}${field(t('الأستاذ','Teacher'),'sourceInstructor')}<label>${t('حالة الملفات','Visibility')}<select name="status">${options([['draft',t('مسودة','Draft')],['published',t('منشور','Published')]],'draft')}</select></label><label class="check wide"><input type="checkbox" name="rightsConfirmed" required>${t('عندي إذن النشر أو رخصة تسمح بذلك؛ الملفات ليست كتبًا مدفوعة.','I have permission or a license to publish these files; they are not paid books.')}</label></form></section><section class="card"><h2>02 / ${t('أضف وراجع الملفات','Add & review files')}</h2><label class="drop-area">${icon('upload')}<b>${t('اختار ملفات من جهازك','Choose files from your device')}</b><small class="hint">PDF · Word · PowerPoint · Images · ZIP</small><input id="courseUpload" type="file" multiple></label><div id="uploadQueue">${queueHTML()}</div><div class="actions" style="margin-top:20px"><button class="primary" data-action="uploadCourses" ${state.uploading?'disabled':''}>${t('ارفع الملفات الجاهزة','Upload ready files')}</button></div><div class="hint" style="margin-top:12px">${t('ملفات كبيرة؟ نستعمل رفع مقسّم آليًا. تقدر تعاود أي ملف فشل.','Large files use multipart upload automatically. Failed files can be retried.')}</div></section>`;}
function queueHTML(){return state.queue.map((x,i)=>`<div class="upload-row"><div><b>${esc(x.file.name)}</b><small>${fmt(x.file.size)} · ${esc(x.error||({ready:t('جاهز','Ready'),done:t('تم الرفع','Uploaded'),uploading:t('جاري الرفع','Uploading')}[x.status]||x.status))}</small><div class="progress"><i style="width:${x.progress||0}%"></i></div></div><input data-queue-name="${i}" value="${esc(x.name)}" aria-label="${t('اسم الملف الظاهر','Display name')}" ${x.status==='done'?'disabled':''}><button data-remove-upload="${i}" ${x.status==='uploading'?'disabled':''}>${t('إزالة','Remove')}</button></div>`).join('');}
function refreshSubjects(){const form=$('#uploadContext');if(!form)return;const f=Object.fromEntries(new FormData(form));const list=new Map(state.static.concat(state.files).filter(x=>x.licence===f.licence&&String(x.year)===f.year&&String(x.semester)===f.semester).map(x=>[x.subjectId,x.subjectName]));$('#uploadSubject').innerHTML=options([...list],null)+`<option value="__new__">+ ${t('مادة جديدة','New subject')}</option>`;$('#newSubject').hidden=$('#uploadSubject').value!=='__new__';}
function configField(label,path,value,type='text'){return `<label>${label}${type==='textarea'?`<textarea data-config="${path}" rows="3">${esc(value)}</textarea>`:`<input data-config="${path}" value="${esc(value)}" type="${type}">`}</label>`;}
function faq(){const c=state.faq;if(!c)return '<div class="loading">…</div>';return head(t('بديس القراي','FAQ / Badis'),t('عدّل الأسئلة والأجوبة ورتّبها. الحفظ يحدّث الموقع مباشرة.','Edit and reorder questions and answers. Saving updates the website immediately.'),`<button class="primary" data-action="saveFaq">${t('حفظ الأسئلة','Save FAQ')}</button>`)+card(t('الإعدادات','Settings'),`<div class="form-grid"><label class="check"><input type="checkbox" data-config="enabled" ${c.enabled?'checked':''}>${t('مفعّل','Enabled')}</label>${configField(t('الاسم','Name'),'name',c.name)}${configField(t('العنوان','Title'),'title',c.title)}${configField(t('السطر الصغير','Small heading'),'eyebrow',c.eyebrow)}<div class="wide">${configField(t('المقدمة','Introduction'),'intro',c.intro,'textarea')}</div></div>`)+`<div class="stack">${c.items.map((x,i)=>`<article class="item-card"><div class="card-head"><span class="number">${String(i+1).padStart(2,'0')}</span><div class="inline-buttons"><button data-faq-up="${i}" ${i===0?'disabled':''}>↑</button><button data-faq-down="${i}" ${i===c.items.length-1?'disabled':''}>↓</button><button class="danger" data-faq-remove="${i}">${t('حذف','Remove')}</button></div></div><label class="check"><input type="checkbox" data-config="items.${i}.enabled" ${x.enabled?'checked':''}>${t('ظاهر','Visible')}</label>${configField(t('السؤال','Question'),`items.${i}.question`,x.question)}${configField(t('الجواب','Answer'),`items.${i}.answer`,x.answer,'textarea')}</article>`).join('')}<button data-action="addFaq">+ ${t('سؤال جديد','Add question')}</button></div>`;}
function mascot(){const c=state.mascot;if(!c)return '<div class="loading">…</div>';return head(t('حما غراب','Hama Ghrab'),t('تحكّم في الظهور، الجمل والردود. الحفظ يحدّث الإعدادات مباشرة.','Control visibility, prompts and replies. Saving updates settings immediately.'),`<button class="primary" data-action="saveMascot">${t('حفظ الحوارات','Save conversations')}</button>`)+card(t('الظهور والشخصية','Character & timing'),`<div class="form-grid"><label class="check"><input type="checkbox" data-config="enabled" ${c.enabled?'checked':''}>${t('إظهار حما غراب','Enable Hama Ghrab')}</label>${configField(t('الاسم','Name'),'name',c.name)}${configField(t('رمز الشخصية','Character symbol'),'emoji',c.emoji)}${configField(t('أقل انتظار بالثواني','Minimum delay (seconds)'),'minDelaySec',c.minDelaySec,'number')}${configField(t('أقصى انتظار','Maximum delay'),'maxDelaySec',c.maxDelaySec,'number')}${configField(t('مرات الظهور في الزيارة','Appearances per visit'),'maxPerSession',c.maxPerSession,'number')}</div>`)+`<div class="stack">${c.scenarios.map((x,i)=>`<article class="item-card"><div class="card-head"><span class="number">${i+1}</span><button class="danger" data-mascot-remove="${i}">${t('حذف الحوار','Remove conversation')}</button></div><label class="check"><input type="checkbox" data-config="scenarios.${i}.enabled" ${x.enabled?'checked':''}>${t('مفعّل','Enabled')}</label>${configField(t('عنوان الحوار','Conversation title'),`scenarios.${i}.title`,x.title)}${configField(t('الجملة','Prompt'),`scenarios.${i}.prompt`,x.prompt,'textarea')}${configField(t('أولوية الظهور (1–20)','Selection weight (1–20)'),`scenarios.${i}.weight`,x.weight,'number')}<div class="grid2">${x.choices.map((ch,j)=>`<div>${configField(t('اختيار الطالب','Student choice'),`scenarios.${i}.choices.${j}.label`,ch.label)}${configField(t('الرد','Reply'),`scenarios.${i}.choices.${j}.reply`,ch.reply,'textarea')}</div>`).join('')}</div><button data-add-choice="${i}" ${x.choices.length>=3?'disabled':''}>+ ${t('اختيار','Choice')}</button></article>`).join('')}<button data-action="addMascot">+ ${t('حوار جديد','New conversation')}</button></div>`;}
function history(){return head(t('سجل نشر الموقع','Website publish history'),t('استرجع نسخة قديمة كمسودة. عاينها ثم انشرها إذا تحب.','Restore a previous version as a draft. Preview it, then publish when ready.'),`<button data-action="backupSite">${t('تنزيل نسخة المحتوى','Download content backup')}</button>`)+card(t('النسخ المحفوظة','Saved versions'),state.versions.length?state.versions.map(v=>`<div class="version"><div><strong>${t('نسخة','Revision')} ${v.revision}</strong><small>${esc(new Date(v.createdAt).toLocaleString(state.lang==='ar'?'ar-TN':'en-GB'))} · ${esc(v.createdBy)}</small></div><button data-restore="${esc(v.id)}">${t('استرجع كمسودة','Restore as draft')}</button></div>`).join(''):empty(t('أول عملية نشر تحفظ أول نسخة هنا.','Your first publish will create the first saved version.')));}
function render(){
  const previous=$('#uploadContext');if(previous)state.uploadContext=Object.fromEntries(new FormData(previous));
  disposeTeachers?.();disposeTeachers=null;
  if(state.tab==='teachers'){shell();disposeTeachers=mountTeachers({root:$('#view'),request:api,language:state.lang,notice,catalog:state.static.concat(state.files),memory:state.teacherWorkspace});return;}
  shell();$('#view').innerHTML=({overview,editor,templates,media,courses,upload,faq,mascot,history}[state.tab]||overview)();
  if(state.tab==='upload'){
    const form=$('#uploadContext');for(const [name,value] of Object.entries(state.uploadContext||{})){const el=form.elements.namedItem(name);if(el&&name!=='subjectId'){if(el.type==='checkbox')el.checked=value==='on';else el.value=value;}}
    refreshSubjects();if(state.uploadContext?.subjectId&&[...$('#uploadSubject').options].some(x=>x.value===state.uploadContext.subjectId))$('#uploadSubject').value=state.uploadContext.subjectId;
    $('#newSubject').hidden=$('#uploadSubject').value!=='__new__';
  }
  if(state.tab==='editor'){
    const frame=$('#sitePreview');frame.addEventListener('load',pushPreview);
    editorTools=mountEditorTools({container:$('.editor-controls'),frame,t,catalog:state.static.concat(state.files),route:state.route,onPick:selectPicked,onNavigate:route=>{state.route=route;state.picked=null;$('#pickedPanel').innerHTML=pickedHTML();},onPanel:()=>{state.selecting=false;const b=$('[data-action=select]');b.classList.remove('active');b.setAttribute('aria-pressed','false');}});
  }
}
async function nav(tab){state.tab=tab;state.picked=null;$('#sidebar').classList.remove('open');render();if(tab==='faq'&&!state.faq){state.faq=(await api('/api/admin/faq')).config;render();}if(tab==='mascot'&&!state.mascot){state.mascot=(await api('/api/admin/mascot')).config;render();}if(tab==='history'){state.versions=(await api('/api/admin/site-versions')).versions;render();}window.scrollTo(0,0);}
function markDirty(){state.previewSequence++;state.dirty=true;const el=$('#saveState');if(el){el.className='status draft';el.textContent=t('تغييرات لم تحفظ','Unsaved changes');}clearTimeout(markDirty.timer);markDirty.timer=setTimeout(pushPreview,100);}
function pushPreview(){const f=$('#sitePreview');if(!f)return;f.contentWindow.postMessage({source:'qrayti-admin',type:'preview',sequence:++state.previewSequence,content:state.content},location.origin);f.contentWindow.postMessage({source:'qrayti-admin',type:'select',enabled:state.selecting},location.origin);}
function adopt(d){state.fields={};state.pendingBound={};state.content=clone(d.draft);state.revision=d.revision;state.publishedRevision=d.publishedRevision;state.dirty=false;}
async function saveDraft(redraw=true){
  // Wait for source identities before saving early typing over an existing visual override.
  if(Object.keys(state.pendingBound).length){
    pushPreview();const deadline=Date.now()+10000;
    while(Object.keys(state.pendingBound).length&&Date.now()<deadline)await new Promise(resolve=>setTimeout(resolve,50));
    if(Object.keys(state.pendingBound).length)throw new Error(t('استنّى المعاينة تكمل التحميل وافتح الرئيسية، ثم عاود الحفظ. نصّك مازال محفوظ هنا.','Wait for the preview to load and open Home, then save again. Your typing is still here.'));
  }
  const sent=JSON.stringify(state.content),result=await send('/api/admin/site-content','PUT',{revision:state.revision,content:JSON.parse(sent)});
  if(JSON.stringify(state.content)===sent)adopt(result);
  else{state.revision=result.revision;state.publishedRevision=result.publishedRevision;state.dirty=true;}
  if(redraw){render();notice(state.dirty?t('حُفظت النسخة السابقة. عندك تعديلات أحدث لم تحفظ بعد.','Earlier draft saved. Your newer edits are still unsaved.'):t('المسودة محفوظة.','Draft saved.'));}
}
function dialog(title,body,actionLabel,action){const el=$('#dialog');el.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-close-dialog aria-label="${t('إغلاق','Close')}">×</button></div><div class="dialog-body">${body}</div><div class="dialog-actions"><button data-close-dialog>${t('إلغاء','Cancel')}</button>${action?`<button id="dialogConfirm" class="primary">${actionLabel}</button>`:''}</div>`;el.showModal();if(action)$('#dialogConfirm').onclick=e=>run(async()=>{await action();el.close();},e.currentTarget);}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function chooseMedia(target){state.media=(await api('/api/admin/media')).items;dialog(t('اختار صورة','Choose an image'),`<p class="hint">${t('ارفع الصور أولًا من مكتبة الصور.','Upload images through the Media library first.')}</p>`+mediaCards(true));$('#dialog').querySelectorAll('[data-use-media]').forEach(b=>b.onclick=()=>{if(target==='picked'){state.picked.value=b.dataset.useMedia;$('#pickedValue').value=b.dataset.useMedia;}else{setPath(state.content,target,b.dataset.useMedia);markDirty();render();}$('#dialog').close();});}
async function editFile(id){
  const file=allFiles().find(x=>x.id===id);if(!file)return;const readonly=file.origin==='static';
  const destination=!readonly?`<label>${t('الإجازة','Licence')}<select name="licence">${options([['info','Sciences de l’Informatique'],['lt','LT'],['lce','LCE']],file.licence)}</select></label><label>${t('السنة','Year')}<select name="year">${options([[1,'1'],[2,'2']],file.year)}</select></label><label>${t('السداسي','Semester')}<select name="semester">${options([[1,'S1'],[2,'S2']],file.semester)}</select></label><label>${t('الشعبة','Track')}<select name="track">${options([['common',t('جذع مشترك','Common')],['genie','Génie Logiciel'],['multimedia','Multimédia']],file.track)}</select></label>`:'';
  dialog(t('تعديل الملف','Edit file'),`<form id="fileEdit" class="form-grid">${field(t('الاسم الظاهر','Display name'),'displayName',file.displayName,'text',true)}${field(t('المجموعة / الشابتر','Group / chapter'),'group',file.group)}<label>${t('الحالة','Status')}<select name="status">${options([['published',t('منشور','Published')],...(!readonly?[['draft',t('مسودة','Draft')]]:[]),['hidden',t('مخفي','Hidden')]],file.status)}</select></label>${field(t('الجامعة','University'),'sourceUniversity',file.sourceUniversity)}${field(t('المؤسسة','Institution'),'sourceInstitution',file.sourceInstitution)}${field(t('الأستاذ','Teacher'),'sourceInstructor',file.sourceInstructor)}${destination}${!readonly?`${field(t('اسم المادة','Subject name'),'subjectName',file.subjectName)}${field(t('معرّف المادة','Subject ID'),'subjectId',file.subjectId)}${field(t('اسم المادة بالعربية','Arabic subject name'),'subjectAr',file.subjectAr)}${field(t('اختصار المادة','Subject abbreviation'),'subjectAbbr',file.subjectAbbr)}${field(t('عنوان الشابتر الكامل','Full chapter title'),'groupTitle',file.groupTitle)}${field(t('موضوع الملف','Topic'),'topic',file.topic)}<label>${t('القسم','Category')}<select name="category">${options(categories,file.category)}</select></label>`:''}</form><p class="hint">${t('هذه التغييرات تحفظ مباشرة في الكاتالوغ.','These changes save directly to the catalog.')}</p>`,t('حفظ التغييرات','Save changes'),async()=>{
    const meta={...file,...Object.fromEntries(new FormData($('#fileEdit'))),originalGroup:file.group};
    if(!meta.displayName.trim())throw new Error(t('اسم الملف مطلوب','File name is required'));
    if(readonly)await send('/api/admin/static-items','PUT',{id,meta});
    else{
      if(meta.group!==file.group&&meta.groupTitle===(file.groupTitle||''))meta.groupTitle=meta.group;
      if(meta.category!==file.category){meta.categoryName=categories.find(x=>x[0]===meta.category)?.[1];meta.categoryAr='';}
      await send('/api/admin/item/'+encodeURIComponent(id),'PATCH',meta);
    }
    await loadFiles();render();notice(t('تم حفظ الملف.','File saved.'));
  });
}
async function loadFiles(){const [a,b]=await Promise.all([api('/api/admin/export'),api('/api/admin/static-items')]);state.files=a.items;state.overrides=b.items;}
function xhr(url,method,body,onProgress){return new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open(method,url);x.upload.onprogress=e=>onProgress(e.loaded,e.total);x.onload=()=>{let d;try{d=JSON.parse(x.responseText);}catch{d={error:'HTTP '+x.status};}x.status>=200&&x.status<300?resolve(d):reject(new Error(d.error));};x.onerror=()=>reject(new Error(t('انقطع الاتصال. عاود المحاولة.','Connection lost. Please retry.')));x.send(body);});}
function renderQueue(){const queue=$('#uploadQueue');if(queue)queue.innerHTML=queueHTML();}
async function uploadFile(item,meta){const progress=(l,total)=>{item.progress=total?Math.round(l/total*100):0;renderQueue();};if(item.file.size<=90*1024*1024){const f=new FormData();f.append('file',item.file);f.append('meta',JSON.stringify(meta));return xhr('/api/admin/upload','POST',f,progress);}const c=await send('/api/admin/multipart?action=create','POST',{fileName:item.file.name,mime:item.file.type||'application/octet-stream',size:item.file.size,meta}),parts=[],size=8*1024*1024;const params=new URLSearchParams({key:c.key,uploadId:c.uploadId});try{for(let i=0;i<Math.ceil(item.file.size/size);i++){const offset=i*size;parts.push(await xhr('/api/admin/multipart?action=part&'+params+'&partNumber='+(i+1),'PUT',item.file.slice(offset,offset+size),(l)=>progress(offset+l,item.file.size)));}return await send('/api/admin/multipart?action=complete&'+params,'POST',{id:c.id,fileName:item.file.name,mime:item.file.type,size:item.file.size,meta,parts});}catch(e){await api('/api/admin/multipart?action=abort&'+params,{method:'DELETE'}).catch(()=>{});throw e;}}
async function uploadCourses(){if(state.uploading)return;const f=Object.fromEntries(new FormData($('#uploadContext')));if(f.rightsConfirmed!=='on')throw new Error(t('أكد حق نشر الملفات أولًا.','Confirm publishing rights first.'));const subject=state.static.concat(state.files).find(x=>x.subjectId===f.subjectId);const meta={...f,year:+f.year,semester:+f.semester,rightsConfirmed:true,subjectId:f.subjectId==='__new__'?f.newSubjectId:subject?.subjectId,subjectName:f.subjectId==='__new__'?f.subjectName:subject?.subjectName,sourceBasis:'admin'};if(!meta.subjectId||!meta.subjectName)throw new Error(t('اختار مادة أو كمّل بيانات المادة الجديدة.','Choose a subject or complete the new subject details.'));if(!state.queue.some(x=>x.status!=='done'))throw new Error(t('أضف ملفات أولًا.','Add files first.'));state.uploading=true;try{for(const item of state.queue.filter(x=>x.status!=='done')){item.status='uploading';item.error='';try{await uploadFile(item,{...meta,displayName:item.name});item.status='done';item.progress=100;}catch(e){item.status='failed';item.error=e.message;}renderQueue();}await loadFiles();notice(t('انتهى الرفع. راجع حالة كل ملف.','Upload finished. Check each file’s status.'));}finally{state.uploading=false;const b=$('[data-action="uploadCourses"]');if(b)b.disabled=false;}}
async function boot(){const session=await api('/api/admin/session');state.session=session;const content=await api('/api/admin/site-content');adopt(content);const [idx,media,versions]=await Promise.all([fetch('/admin/static-index.json').then(r=>{if(!r.ok)throw new Error('Library index unavailable');return r.json();}),api('/api/admin/media'),api('/api/admin/site-versions'),loadFiles()]);state.static=idx.items||[];state.media=media.items;state.versions=versions.versions;render();}
$('#loginForm').addEventListener('submit',e=>{e.preventDefault();run(async()=>{const form=e.currentTarget;await send('/api/admin-login','POST',{password:new FormData(form).get('password')});await boot();},e.submitter);});

function receiveFields(fields){
  // Display effective preview copy without saving implicit defaults into the draft.
  for(const [path,entry] of Object.entries(fields||{})){
    const input=document.querySelector('[data-bind="'+path+'"]');
    if(!input||typeof entry.value!=='string')continue;
    const pending=Object.hasOwn(state.pendingBound,path);
    const keepTyping=pending||(input===document.activeElement&&input.dataset.edited==='true');
    // Always retain source identity, even while protecting the active input's text.
    state.fields[path]={...entry,value:keepTyping?input.value:entry.value};
    if(pending&&entry.original){editBound(input);markDirty();}
    else if(!keepTyping)input.value=entry.value;
  }
}
function editBound(input){
  const path=input.dataset.bind,value=input.type==='checkbox'?input.checked:input.value,field=state.fields[path];
  input.dataset.edited='true';
  if(previewTextPaths.has(path)&&!field?.original)state.pendingBound[path]=value;
  else delete state.pendingBound[path];
  setPath(state.content,path,value);
  if(field?.original){
    // A previous click-to-edit override must not mask an edit made in this form.
    const matches=x=>!x.attribute&&x.original===field.original;
    const hasGlobal=state.content.texts.some(x=>matches(x)&&x.route==='*');
    state.content.texts=state.content.texts.filter(x=>!(matches(x)&&x.route===field.route));
    if(hasGlobal)state.content.texts.push({id:crypto.randomUUID(),original:field.original,route:field.route,value:value||field.original});
    $('#editList').innerHTML=editsHTML();
  }
  if(field)state.fields[path]={...field,value};
}

document.addEventListener('input',e=>{const el=e.target;if(el.dataset.bind){editBound(el);markDirty();}if(el.dataset.config){setPath(state[state.tab],el.dataset.config,el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value);}if(el.id==='courseSearch'){state.query=el.value;state.page=1;$('#courseRows').innerHTML=courseRows();}if(el.dataset.queueName!==undefined)state.queue[Number(el.dataset.queueName)].name=el.value;});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='courseFilter'){state.filter=el.value;state.page=1;$('#courseRows').innerHTML=courseRows();}if(el.closest('#uploadContext')&&['licence','year','semester'].includes(el.name))refreshSubjects();if(el.id==='uploadSubject')$('#newSubject').hidden=el.value!=='__new__';if(el.id==='courseUpload'){for(const file of el.files)state.queue.push({file,name:file.name.replace(/\.[^.]+$/,''),status:'ready',progress:0});el.value='';$('#uploadQueue').innerHTML=queueHTML();}if(el.matches('[data-upload-media]'))run(async()=>{for(const file of el.files){const form=new FormData();form.append('file',file);await api('/api/admin/media',{method:'POST',body:form});}state.media=(await api('/api/admin/media')).items;render();notice(t('تم رفع الصور.','Images uploaded.'));});});
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-nav]');if(!b)return;if(b.hasAttribute('data-theme-toggle')){toggleTheme();return;}if(b.dataset.lang){state.lang=b.dataset.lang;localStorage.setItem('qrayti-admin-language',state.lang);state.session?render():login();return;}if(b.dataset.nav){run(()=>nav(b.dataset.nav));return;}if(b.hasAttribute('data-close-dialog')){$('#dialog').close();return;}if(b.dataset.mediaTarget){run(()=>chooseMedia(b.dataset.mediaTarget));return;}if(b.dataset.clearImage){setPath(state.content,b.dataset.clearImage,'');markDirty();render();return;}if(b.dataset.template){state.content.template=b.dataset.template;markDirty();run(()=>nav('editor'));return;}if(b.dataset.device){state.device=b.dataset.device;$('.preview-body').classList.toggle('phone',state.device==='phone');document.querySelectorAll('[data-device]').forEach(x=>x.classList.toggle('active',x.dataset.device===state.device));return;}if(b.hasAttribute('data-preview-home')){$('#sitePreview').src='/?admin-preview=1#/welcome';return;}if(b.dataset.removeEdit){state.content[b.dataset.kind]=state.content[b.dataset.kind].filter(x=>x.id!==b.dataset.removeEdit);markDirty();$('#editList').innerHTML=editsHTML();return;}if(b.dataset.editFile){run(()=>editFile(b.dataset.editFile));return;}if(b.dataset.page){state.page=+b.dataset.page;$('#courseRows').innerHTML=courseRows();return;}if(b.dataset.removeUpload!==undefined){state.queue.splice(+b.dataset.removeUpload,1);$('#uploadQueue').innerHTML=queueHTML();return;}if(b.dataset.copyMedia){run(async()=>{await navigator.clipboard.writeText(location.origin+b.dataset.copyMedia);notice(t('تم نسخ الرابط.','URL copied.'));});return;}if(b.dataset.restore){dialog(t('استرجاع نسخة','Restore version'),`<p>${t('سنحفظ النسخة المختارة كمسودة. الموقع الحالي لا يتغير حتى تنشر.','The selected version becomes your draft. The live site changes only after publishing.')}</p>`,t('استرجاع','Restore'),async()=>{adopt(await send('/api/admin/site-content','POST',{action:'restore',id:b.dataset.restore,revision:state.revision}));await nav('editor');});return;}
  for(const [key,op] of [['faqRemove','remove'],['faqUp','up'],['faqDown','down']])if(b.dataset[key]!==undefined){const i=+b.dataset[key],a=state.faq.items;if(op==='remove')a.splice(i,1);else{const j=i+(op==='up'?-1:1);[a[i],a[j]]=[a[j],a[i]];}render();return;}
  if(b.dataset.mascotRemove!==undefined){state.mascot.scenarios.splice(+b.dataset.mascotRemove,1);render();return;}if(b.dataset.addChoice!==undefined){state.mascot.scenarios[+b.dataset.addChoice].choices.push({label:'',reply:''});render();return;}
  const action=b.dataset.action;if(!action)return;
  run(async()=>{if(action==='menu')$('#sidebar').classList.toggle('open');if(action==='logout'){if(state.dirty&&!confirm(t('عندك تغييرات غير محفوظة. تخرج؟','You have unsaved changes. Sign out?')))return;await api('/api/admin-login',{method:'DELETE'});state.session=null;login();}if(action==='save')await saveDraft();if(action==='select'){state.selecting=!state.selecting;b.classList.toggle('active',state.selecting);b.setAttribute('aria-pressed',state.selecting);pushPreview();}if(action==='publish')dialog(t('انشر تغييرات الموقع؟','Publish website changes?'),`<p>${t('ستظهر المسودة الحالية لكل زوار الموقع. القالب المختار:','The current draft becomes visible to all visitors. Selected template:')} <b>${esc(state.content.template)}</b></p><p>${state.content.texts.length} ${t('تعديل نص','text overrides')} · ${state.content.images.length} ${t('تعديل صورة','image overrides')}</p><p class="hint">${t('نحفظ نسخة في السجل قبل أي استرجاع لاحق.','This published version will be available in history.')}</p>`,t('نشر الآن','Publish now'),async()=>{if(state.dirty)await saveDraft(false);adopt(await send('/api/admin/site-content','POST',{action:'publish',revision:state.revision}));state.versions=(await api('/api/admin/site-versions')).versions;render();notice(t('تم النشر. افتح الموقع لتشوف التغييرات.','Published. Open the website to see your changes.'));});
    if(action==='applyPicked'){const p=state.picked,route=$('#pickedGlobal').checked?'*':p.route,kind=p.kind!=='image'?'texts':'images',entry={id:crypto.randomUUID(),route,original:p.original,...(kind==='texts'?{value:$('#pickedValue').value,...(p.attribute?{attribute:p.attribute}:{})}:{src:$('#pickedValue').value,alt:$('#pickedAlt').value})};const old=state.content[kind].findIndex(x=>x.original===p.original&&x.route===route&&(x.attribute||'')===(p.attribute||''));if(old>=0)state.content[kind][old]=entry;else state.content[kind].push(entry);markDirty();$('#editList').innerHTML=editsHTML();notice(t('تطبّق في المعاينة. احفظ وانشر عندما تكون جاهزًا.','Applied to preview. Save and publish when ready.'));}
    if(action==='uploadCourses')await uploadCourses();if(action==='export')download('qrayti-catalog-backup.json',{exportedAt:new Date().toISOString(),items:allFiles()});if(action==='backupSite')download('qrayti-site-content.json',await api('/api/admin/site-content'));
    if(action==='addFaq'){state.faq.items.push({id:crypto.randomUUID(),enabled:true,question:'',answer:''});render();}if(action==='saveFaq'){if(state.faq.items.some(x=>!x.question.trim()||!x.answer.trim()))throw new Error(t('كمّل كل سؤال وجواب قبل الحفظ.','Complete every question and answer before saving.'));state.faq.baseVersion=25;state.faq=(await send('/api/admin/faq','PUT',{config:state.faq})).config;notice(t('تم حفظ الأسئلة.','FAQ saved.'));}
    if(action==='addMascot'){state.mascot.scenarios.push({id:crypto.randomUUID(),enabled:true,title:'',weight:2,prompt:'',choices:[{label:'',reply:''}]});render();}if(action==='saveMascot'){if(state.mascot.scenarios.some(x=>!x.prompt.trim()||x.choices.some(y=>!y.label.trim()||!y.reply.trim())))throw new Error(t('كمّل الجمل والردود قبل الحفظ.','Complete prompts and replies before saving.'));if(state.mascot.maxDelaySec<state.mascot.minDelaySec)throw new Error(t('أقصى انتظار يجب أن يكون أكبر من أقل انتظار.','Maximum delay must be at least the minimum.'));state.mascot=(await send('/api/admin/mascot','PUT',{config:state.mascot})).config;notice(t('تم حفظ الحوارات.','Conversations saved.'));}
  },b);
});
addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==$('#sitePreview')?.contentWindow||e.data?.source!=='qrayti-site')return;const d=e.data;if(d.route){state.route=d.route;$('#previewAddress').textContent=d.route;}if(d.type==='ready')pushPreview();if(d.type==='fields'&&d.sequence===state.previewSequence)receiveFields(d.fields);if(d.type==='inventory')editorTools?.update(d);if(d.type==='picked')selectPicked(d);});
addEventListener('beforeunload',e=>{if(state.dirty||state.uploading){e.preventDefault();e.returnValue='';}});
login();boot().catch(e=>{if(e.status!==401){$('#loginError').textContent=t('تعذّر تحميل الإدارة: ','Could not load admin: ')+e.message;}state.session=null;});
